<span class="line"><span class="token keyword">assert</span> <span class="token builtin">round</span><span class="token punctuation">(</span><span class="token number">12_345</span> <span class="token operator">*</span> <span class="token number">1e-04</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">1.23</span></span>
